"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7193],{60839:function(e,t,a){a.d(t,{W:function(){return n}});class n{addDocument(e){this.documents.set(e.id,e),this.indexDocument(e)}addDocuments(e){e.forEach(e=>this.addDocument(e))}indexDocument(e){let t="".concat(e.title," ").concat(e.content," ").concat(e.summary||""," ").concat((e.tags||[]).join(" "));this.tokenize(t).forEach(t=>{this.invertedIndex.has(t)||this.invertedIndex.set(t,new Set),this.invertedIndex.get(t).add(e.id)})}tokenize(e){return e.toLowerCase().replace(/[^\w\s-]/g," ").split(/\s+/).filter(e=>e.length>2).map(e=>this.stem(e))}stem(e){for(let t of["ing","ed","s","es","er","est","ly","tion","sion"])if(e.endsWith(t)&&e.length>t.length+2)return e.slice(0,-t.length);return e}search(e,t){let{category:a,limit:n=50,minScore:s=.1}=t||{},i=this.tokenize(e);if(0===i.length)return[];let r=new Map;i.forEach(e=>{(this.invertedIndex.get(e)||new Set).forEach(t=>{r.has(t)||r.set(t,{score:0,matches:new Set});let a=r.get(t);a.score+=1,a.matches.add(e)})});let o=[];return r.forEach((e,t)=>{var n;let{score:r,matches:l}=e,c=this.documents.get(t);if(!c||a&&c.category!==a)return;let h=r/i.length,d=h*Math.log(this.documents.size/(l.size+1))*(i.some(e=>c.title.toLowerCase().includes(e))?1.5:1)*((null===(n=c.tags)||void 0===n?void 0:n.some(e=>i.some(t=>e.toLowerCase().includes(t))))?1.3:1);d>=s&&o.push({document:c,score:d,matches:Array.from(l)})}),o.sort((e,t)=>t.score-e.score),o.slice(0,n)}getCategories(){let e=new Set;return this.documents.forEach(t=>{t.category&&e.add(t.category)}),Array.from(e).sort()}getDocumentCount(){return this.documents.size}clear(){this.documents.clear(),this.invertedIndex.clear()}constructor(){this.documents=new Map,this.invertedIndex=new Map}}},88976:function(e){e.exports=JSON.parse('{"title_en":"Space Handbook","title_ar":"دليل الفضاء","chapters":[{"id":"origins","title_en":"Origins","title_ar":"الأصول","icon":"\uD83D\uDCA5","summary_en":"The birth of the universe, from the Big Bang to the first structures","summary_ar":"ولادة الكون، من الانفجار العظيم إلى أول البنى","sections":[{"title_en":"The Big Bang","title_ar":"الانفجار العظيم","content_en":"The Big Bang theory describes the origin of our universe. About 13.8 billion years ago, all matter, energy, space, and time were compressed into an infinitely dense point called a singularity. In an instant, this point expanded rapidly, creating the universe we know today. Within the first second, the universe expanded from smaller than an atom to the size of a galaxy. This expansion continues today, and we can still observe the afterglow of this event in the cosmic microwave background radiation.","content_ar":"نظرية الانفجار العظيم تصف أصل كوننا. منذ حوالي 13.8 مليار سنة، كانت كل المادة والطاقة والفضاء والزمن مضغوطة في نقطة كثيفة بلا حدود تسمى التفرد. في لحظة، توسعت هذه النقطة بسرعة، مكونة الكون الذي نعرفه اليوم. خلال الثانية الأولى، توسع الكون من أصغر من ذرة إلى حجم مجرة. هذا التوسع مستمر اليوم، ويمكننا رصد توهج هذا الحدث في إشعاع الخلفية الكوني الميكروي."},{"title_en":"Cosmic Inflation","title_ar":"التضخم الكوني","content_en":"Cosmic inflation occurred in the first 10^-32 seconds after the Big Bang. During this period, the universe expanded faster than the speed of light, growing by a factor of at least 10^26. This rapid expansion explains why the universe appears uniform in all directions and why we don\'t see magnetic monopoles. The theory was proposed by Alan Guth in 1980 and has been supported by observations of the cosmic microwave background.","content_ar":"حدث التضخم الكوني في أول 10^-32 ثانية بعد الانفجار العظيم. خلال هذه الفترة، توسع الكون أسرع من سرعة الضوء، متضخماً بعامل 10^26 على الأقل. هذا التوسع السريع يفسر لماذا يبدو الكون موحداً في جميع الاتجاهات ولماذا لا نرى أحاديات القطب المغناطيسي. النظرية اقترحها آلان غوث في 1980 وتم دعمها بملاحظات إشعاع الخلفية الكوني الميكروي."},{"title_en":"First Light","title_ar":"أول ضوء","content_en":"First light refers to the moment when the first stars began to shine, ending the cosmic Dark Ages. This occurred about 100-200 million years after the Big Bang. These first stars were massive and hot, emitting intense ultraviolet radiation that began to reionize the neutral hydrogen gas filling the universe. This era of reionization lasted until about 1 billion years after the Big Bang.","content_ar":"أول ضوء يشير إلى اللحظة التي بدأت فيها أول النجوم بالتوهج، منهية العصور المظلمة الكونية. حدث هذا بعد حوالي 100-200 مليون سنة من الانفجار العظيم. كانت هذه النجوم الأولى ضخمة وساخنة، تبث إشعاعاً فوق بنفسجياً شديداً بدأ بإعادة تأين غاز الهيدروجين المحايد الذي ملأ الكون. استمر عصر إعادة التأين هذا حتى حوالي مليار سنة بعد الانفجار العظيم."}]},{"id":"matter-energy","title_en":"Matter & Energy","title_ar":"المادة والطاقة","icon":"⚛️","summary_en":"The fundamental building blocks of the universe and the forces that govern them","summary_ar":"لبنات البناء الأساسية للكون والقوى التي تحكمها","sections":[{"title_en":"Dark Matter","title_ar":"المادة المظلمة","content_en":"Dark matter makes up about 27% of the universe\'s total mass-energy content, yet we cannot see it directly. It doesn\'t emit, absorb, or reflect light. We know it exists because of its gravitational effects on visible matter. Galaxies rotate faster than they should based on visible matter alone, and galaxy clusters hold together despite insufficient visible mass. Dark matter likely consists of exotic particles that don\'t interact with electromagnetic forces.","content_ar":"المادة المظلمة تشكل حوالي 27% من إجمالي محتوى كتلة-طاقة الكون، لكننا لا نستطيع رؤيتها مباشرة. لا تبعث أو تمتص أو تعكس الضوء. نعرف أنها موجودة بسبب تأثيراتها الجاذبية على المادة المرئية. المجرات تدور أسرع مما يجب بناءً على المادة المرئية وحدها، وعناقيد المجرات تبقى متماسكة رغم عدم كفاية الكتلة المرئية. المادة المظلمة على الأرجح تتكون من جسيمات غريبة لا تتفاعل مع القوى الكهرومغناطيسية."},{"title_en":"Dark Energy","title_ar":"الطاقة المظلمة","content_en":"Dark energy is the mysterious force causing the universe\'s expansion to accelerate. It makes up about 68% of the universe. Discovered in 1998 through observations of distant supernovae, dark energy counteracts gravity on cosmic scales. Unlike dark matter, which pulls matter together, dark energy pushes space apart. Its nature remains one of the greatest mysteries in physics, with theories ranging from a cosmological constant to dynamic fields that change over time.","content_ar":"الطاقة المظلمة هي القوة الغامضة التي تسبب تسارع توسع الكون. تشكل حوالي 68% من الكون. اكتُشفت في 1998 من خلال ملاحظات المستعرات العظمى البعيدة، الطاقة المظلمة تقاوم الجاذبية على المقاييس الكونية. على عكس المادة المظلمة التي تسحب المادة معاً، الطاقة المظلمة تدفع الفضاء بعيداً. طبيعتها تبقى من أعظم الألغاز في الفيزياء، بنظريات تتراوح من ثابت كوني إلى حقول ديناميكية تتغير مع الزمن."},{"title_en":"Fundamental Forces","title_ar":"القوى الأساسية","content_en":"The universe is governed by four fundamental forces: gravity, electromagnetism, the strong nuclear force, and the weak nuclear force. Gravity is the weakest but acts over infinite distances, shaping galaxies and cosmic structure. Electromagnetism binds atoms and molecules. The strong force holds atomic nuclei together, while the weak force governs radioactive decay. At high energies, electromagnetism and the weak force unify into the electroweak force.","content_ar":"الكون محكوم بأربع قوى أساسية: الجاذبية، الكهرومغناطيسية، القوة النووية القوية، والقوة النووية الضعيفة. الجاذبية الأضعف لكنها تعمل على مسافات لا نهائية، مشكلة المجرات والبنية الكونية. الكهرومغناطيسية تربط الذرات والجزيئات. القوة القوية تمسك النوى الذرية معاً، بينما القوة الضعيفة تحكم الاضمحلال الإشعاعي. عند الطاقات العالية، الكهرومغناطيسية والقوة الضعيفة تتحدان في القوة الكهروضعيفة."}]},{"id":"stars","title_en":"Stars","title_ar":"النجوم","icon":"⭐","summary_en":"The cosmic furnaces that light up the universe and forge the elements of life","summary_ar":"الأفران الكونية التي تنير الكون وتشكل عناصر الحياة","sections":[{"title_en":"Star Formation","title_ar":"تكوين النجوم","content_en":"Stars form in giant molecular clouds, regions of dense gas and dust in galaxies. When a cloud becomes dense enough, gravity causes it to collapse. As it collapses, it fragments into smaller clumps, each potentially becoming a star. The core heats up from gravitational energy, and when it reaches about 10 million Kelvin, nuclear fusion begins. Hydrogen atoms fuse into helium, releasing enormous amounts of energy. This energy counteracts gravity, and the star reaches equilibrium, beginning its main sequence lifetime.","content_ar":"تتشكل النجوم في سحب جزيئية عملاقة، مناطق من الغاز والغبار الكثيف في المجرات. عندما تصبح السحابة كثيفة بما يكفي، تسبب الجاذبية انهيارها. بينما تنهار، تتفتت إلى كتل أصغر، كل واحدة قد تصبح نجماً. القلب يسخن من طاقة الجاذبية، وعندما يصل إلى حوالي 10 ملايين كلفن، يبدأ الاندماج النووي. ذرات الهيدروجين تندمج إلى هيليوم، مطلقة كميات هائلة من الطاقة. هذه الطاقة تقاوم الجاذبية، والنجم يصل إلى التوازن، مبتدئاً عمره في التسلسل الرئيسي."},{"title_en":"Stellar Lifecycle","title_ar":"دورة حياة النجم","content_en":"A star\'s life depends on its mass. Low-mass stars like red dwarfs can burn for trillions of years. Medium-mass stars like our Sun spend about 10 billion years fusing hydrogen, then expand into red giants before shedding their outer layers as planetary nebulae, leaving white dwarf cores. Massive stars live fast and die young, exploding as supernovae after just millions of years, leaving behind neutron stars or black holes. These explosions seed the universe with heavy elements essential for planets and life.","content_ar":"حياة النجم تعتمد على كتلته. النجوم منخفضة الكتلة مثل الأقزام الحمراء يمكن أن تحترق لتريليونات السنين. النجوم متوسطة الكتلة مثل شمسنا تقضي حوالي 10 مليارات سنة في اندماج الهيدروجين، ثم تتوسع إلى عمالقة حمراء قبل أن تتخلص من طبقاتها الخارجية كسديم كوكبي، تاركة نوى أقزام بيضاء. النجوم الضخمة تعيش بسرعة وتموت صغيرة، منفجرة كمستعرات عظمى بعد ملايين السنين فقط، تاركة وراءها نجوم نيوترونية أو ثقوب سوداء. هذه الانفجارات تزرع الكون بعناصر ثقيلة ضرورية للكواكب والحياة."},{"title_en":"Star Classification","title_ar":"تصنيف النجوم","content_en":"Stars are classified by temperature and luminosity using the Hertzsprung-Russell diagram. The main sequence includes stars fusing hydrogen: O-type (hottest, blue-white) to M-type (coolest, red). Giants and supergiants are evolved stars that have left the main sequence. White dwarfs are stellar remnants. Our Sun is a G-type main sequence star, yellow-white, with a surface temperature of about 5,800 Kelvin. The classification helps astronomers understand stellar evolution and the universe\'s history.","content_ar":"النجوم مصنفة حسب الحرارة واللمعان باستخدام مخطط هرتزبرونغ-راسل. التسلسل الرئيسي يشمل النجوم التي تندمج الهيدروجين: من النوع O (الأكثر حرارة، أزرق-أبيض) إلى النوع M (الأبرد، أحمر). العمالقة والعمالقة العظمى نجوم متطورة تركت التسلسل الرئيسي. الأقزام البيضاء بقايا نجمية. شمسنا نجم تسلسل رئيسي من النوع G، أصفر-أبيض، بدرجة حرارة سطح حوالي 5,800 كلفن. التصنيف يساعد الفلكيين على فهم التطور النجمي وتاريخ الكون."}]},{"id":"galaxies","title_en":"Galaxies","title_ar":"المجرات","icon":"\uD83C\uDF0C","summary_en":"Vast cosmic cities of stars, gas, and dark matter","summary_ar":"مدن كونية شاسعة من النجوم والغاز والمادة المظلمة","sections":[{"title_en":"Galaxy Types","title_ar":"أنواع المجرات","content_en":"Galaxies come in three main types: spiral, elliptical, and irregular. Spiral galaxies like the Milky Way have rotating disks with spiral arms, central bulges, and halos of dark matter. They contain gas and dust for ongoing star formation. Elliptical galaxies are smooth, featureless ellipsoids containing mostly old stars with little gas. They range from nearly spherical to highly flattened. Irregular galaxies lack defined structure, often resulting from galactic collisions. Our Milky Way is a barred spiral galaxy, about 100,000 light-years across, containing 100-400 billion stars.","content_ar":"المجرات تأتي في ثلاثة أنواع رئيسية: حلزونية، إهليلجية، وغير منتظمة. المجرات الحلزونية مثل درب التبانة لها أقراص دوارة بأذرع حلزونية، انتفاخات مركزية، وهالات من المادة المظلمة. تحتوي على غاز وغبار لتكوين نجوم مستمر. المجرات الإهليلجية ناعمة، إهليلجيات بلا ملامح تحتوي معظمها على نجوم قديمة مع قليل من الغاز. تتراوح من كروية تقريباً إلى مسطحة بشدة. المجرات غير المنتظمة تفتقر لبنية محددة، غالباً نتيجة تصادمات مجرية. درب التبانة مجرة حلزونية قضيبية، حوالي 100,000 سنة ضوئية عبر، تحتوي 100-400 مليار نجم."},{"title_en":"Galaxy Formation","title_ar":"تكوين المجرات","content_en":"Galaxies began forming about 400 million years after the Big Bang, when gravity pulled matter together into the first structures. Small protogalaxies merged to form larger galaxies. The Milky Way likely formed through hierarchical assembly, with smaller galaxies merging over billions of years. Dark matter played a crucial role, providing the gravitational scaffolding around which visible matter collected. Today, galaxies continue to evolve through mergers, star formation, and interactions with their environments.","content_ar":"المجرات بدأت تتكون بعد حوالي 400 مليون سنة من الانفجار العظيم، عندما جذبت الجاذبية المادة معاً في أول البنى. المجرات الأولية الصغيرة اندمجت لتشكل مجرات أكبر. درب التبانة على الأرجح تشكلت من خلال التجميع الهرمي، مع مجرات أصغر تندمج على مدى مليارات السنين. المادة المظلمة لعبت دوراً حاسماً، موفرة السقالة الجاذبية التي حولها تجمعت المادة المرئية. اليوم، المجرات تستمر في التطور من خلال الاندماجات، تكوين النجوم، والتفاعلات مع بيئاتها."},{"title_en":"Galaxy Clusters","title_ar":"عناقيد المجرات","content_en":"Galaxies are not randomly distributed but form groups and clusters. The Local Group contains the Milky Way, Andromeda, and about 50 smaller galaxies. Galaxy clusters contain hundreds to thousands of galaxies bound by gravity, embedded in halos of hot gas and dark matter. Superclusters are even larger structures, the largest known cosmic formations. The Virgo Supercluster contains the Local Group and spans about 110 million light-years. These structures reveal the large-scale organization of the universe.","content_ar":"المجرات ليست موزعة عشوائياً بل تشكل مجموعات وعناقيد. المجموعة المحلية تحتوي على درب التبانة، أندروميدا، وحوالي 50 مجرة أصغر. عناقيد المجرات تحتوي على مئات إلى آلاف المجرات مربوطة بالجاذبية، مغمورة في هالات من الغاز الساخن والمادة المظلمة. العناقيد الفائقة هياكل أكبر، أكبر التكوينات الكونية المعروفة. العنقود الفائق العذراء يحتوي على المجموعة المحلية ويمتد حوالي 110 مليون سنة ضوئية. هذه الهياكل تكشف التنظيم واسع النطاق للكون."}]},{"id":"black-holes","title_en":"Black Holes","title_ar":"الثقوب السوداء","icon":"\uD83D\uDD73️","summary_en":"Regions of spacetime where gravity is so strong that nothing, not even light, can escape","summary_ar":"مناطق من الزمكان حيث الجاذبية قوية جداً حتى لا شيء، حتى الضوء، يمكنه الهروب","sections":[{"title_en":"What Are Black Holes","title_ar":"ما هي الثقوب السوداء","content_en":"Black holes are regions of spacetime where gravity is so intense that nothing, not even light, can escape once it crosses the event horizon. They form when massive stars collapse at the end of their lives, or through other processes that compress matter to extreme densities. The event horizon marks the point of no return. Inside, matter is crushed to a singularity - a point of infinite density. Black holes come in different sizes: stellar-mass (a few to tens of solar masses), intermediate-mass, and supermassive (millions to billions of solar masses) at galaxy centers.","content_ar":"الثقوب السوداء مناطق من الزمكان حيث الجاذبية شديدة جداً حتى لا شيء، حتى الضوء، يمكنه الهروب بمجرد عبوره أفق الحدث. تتكون عندما تنهار النجوم الضخمة في نهاية حياتها، أو من خلال عمليات أخرى تضغط المادة إلى كثافات متطرفة. أفق الحدث يحدد نقطة اللاعودة. في الداخل، المادة تُسحق إلى تفرد - نقطة من الكثافة اللانهائية. الثقوب السوداء تأتي بأحجام مختلفة: كتلة نجمية (بضعة إلى عشرات الكتل الشمسية)، كتلة متوسطة، وعملاقة (ملايين إلى مليارات الكتل الشمسية) في مراكز المجرات."},{"title_en":"Types of Black Holes","title_ar":"أنواع الثقوب السوداء","content_en":"Stellar-mass black holes form from collapsing massive stars and range from about 5 to 50 solar masses. Supermassive black holes, millions to billions of solar masses, lurk at galaxy centers. The Milky Way\'s Sagittarius A* is about 4 million solar masses. Intermediate-mass black holes (hundreds to thousands of solar masses) are rarer and less understood. Primordial black holes, if they exist, would have formed in the early universe. Each type reveals different aspects of physics under extreme conditions.","content_ar":"الثقوب السوداء كتلة نجمية تتكون من انهيار النجوم الضخمة وتتراوح من حوالي 5 إلى 50 كتلة شمسية. الثقوب السوداء العملاقة، ملايين إلى مليارات الكتل الشمسية، تكمن في مراكز المجرات. القوس A* لدرب التبانة حوالي 4 ملايين كتلة شمسية. الثقوب السوداء متوسطة الكتلة (مئات إلى آلاف الكتل الشمسية) أندر وأقل فهماً. الثقوب السوداء البدائية، إن وجدت، كانت لتتشكل في الكون المبكر. كل نوع يكشف جوانب مختلفة من الفيزياء تحت ظروف متطرفة."},{"title_en":"Black Hole Physics","title_ar":"فيزياء الثقوب السوداء","content_en":"Black holes challenge our understanding of physics. Near the event horizon, time dilates and space warps dramatically. The singularity represents a breakdown of general relativity, where quantum gravity effects should dominate. Hawking radiation, predicted by Stephen Hawking, suggests black holes slowly evaporate over eons. The information paradox questions whether information is truly lost in black holes. Recent observations, including the first image of a black hole\'s shadow by the Event Horizon Telescope, confirm predictions and open new questions about these mysterious objects.","content_ar":"الثقوب السوداء تتحدى فهمنا للفيزياء. قرب أفق الحدث، الزمن يتمدد والفضاء ينحني بشكل دراماتيكي. التفرد يمثل انهيار النسبية العامة، حيث تأثيرات الجاذبية الكمية يجب أن تهيمن. إشعاع هوكينغ، المتوقع من ستيفن هوكينغ، يقترح أن الثقوب السوداء تتبخر ببطء على مدى الدهور. مفارقة المعلومات تسأل عما إذا كانت المعلومات تضيع حقاً في الثقوب السوداء. الملاحظات الحديثة، بما في ذلك أول صورة لظل ثقب أسود من تلسكوب أفق الحدث، تؤكد التوقعات وتبعث أسئلة جديدة عن هذه الأجسام الغامضة."}]},{"id":"planets","title_en":"Planets","title_ar":"الكواكب","icon":"\uD83E\uDE90","summary_en":"Diverse worlds orbiting stars, from rocky terrestrial planets to gas giants","summary_ar":"عوالم متنوعة تدور حول النجوم، من الكواكب الصخرية الأرضية إلى العمالقة الغازية","sections":[{"title_en":"Planet Formation","title_ar":"تكوين الكواكب","content_en":"Planets form in protoplanetary disks - flat, rotating disks of gas and dust around young stars. Dust grains collide and stick together, growing into larger bodies called planetesimals. These continue to grow through collisions, eventually forming protoplanets. In the inner solar system, rocky planets form where it\'s too hot for ices. In the outer system, beyond the \'frost line\', gas and ice giants form. The process takes millions of years. Some planets migrate inward or outward during formation. Our solar system\'s planets formed about 4.6 billion years ago, shortly after the Sun\'s birth.","content_ar":"الكواكب تتكون في أقراص كوكبية أولية - أقراص مسطحة دوارة من الغاز والغبار حول النجوم الشابة. حبيبات الغبار تصطدم وتلتصق معاً، متنامية إلى أجسام أكبر تسمى كوكيبات. هذه تستمر في النمو من خلال الاصطدامات، مكونة في النهاية كواكب أولية. في النظام الشمسي الداخلي، الكواكب الصخرية تتكون حيث الجو حار جداً للجليد. في النظام الخارجي، بعد \'خط الصقيع\'، العمالقة الغازية والجليدية تتكون. العملية تستغرق ملايين السنين. بعض الكواكب تهاجر للداخل أو الخارج أثناء التكوين. كواكب نظامنا الشمسي تشكلت منذ حوالي 4.6 مليار سنة، بعد وقت قصير من ولادة الشمس."},{"title_en":"Terrestrial Planets","title_ar":"الكواكب الأرضية","content_en":"Terrestrial planets are rocky worlds with solid surfaces, composed primarily of silicate rocks and metals. The four in our solar system are Mercury, Venus, Earth, and Mars. They\'re relatively small and dense, with thin or no atmospheres (except Earth and Venus). They formed in the inner solar system where temperatures were too high for ices to condense. Earth is unique among them for having liquid water, a protective magnetic field, and active plate tectonics. Mars shows evidence of past water and may have once been habitable. These planets are also called \'inner planets\' due to their proximity to the Sun.","content_ar":"الكواكب الأرضية عوالم صخرية بأسطح صلبة، مكونة في الأساس من صخور سيليكات ومعادن. الأربعة في نظامنا الشمسي هي عطارد والزهرة والأرض والمريخ. صغيرة نسبياً وكثيفة، بغلاف جوي رقيق أو بدون (عدا الأرض والزهرة). تشكلت في النظام الشمسي الداخلي حيث كانت درجات الحرارة عالية جداً لتكثف الجليد. الأرض فريدة بينها لوجود ماء سائل، مجال مغناطيسي واقي، وتكتونيات صفائح نشطة. المريخ يظهر دليلاً على ماء سابق وقد يكون كان قابلاً للسكن مرة. هذه الكواكب تسمى أيضاً \'الكواكب الداخلية\' بسبب قربها من الشمس."},{"title_en":"Gas Giants & Ice Giants","title_ar":"العمالقة الغازية والجليدية","content_en":"Gas giants like Jupiter and Saturn are massive planets composed primarily of hydrogen and helium, with no solid surface. They have thick atmospheres, strong magnetic fields, and many moons. Jupiter, the largest planet, has a Great Red Spot - a storm larger than Earth that has raged for centuries. Ice giants Uranus and Neptune contain more water, methane, and ammonia ices. They\'re smaller than gas giants but still much larger than Earth. These outer planets likely have rocky cores surrounded by layers of compressed gases and ices. They formed beyond the frost line where ices could condense.","content_ar":"العمالقة الغازية مثل المشتري وزحل كواكب ضخمة مكونة في الأساس من الهيدروجين والهيليوم، بدون سطح صلب. لها أغلفة جوية سميكة، مجالات مغناطيسية قوية، والعديد من الأقمار. المشتري، أكبر كوكب، له البقعة الحمراء العظيمة - عاصفة أكبر من الأرض استمرت لقرون. العمالقة الجليدية أورانوس ونبتون تحتوي على المزيد من الماء والميثان والأمونيا الجليدية. أصغر من العمالقة الغازية لكن لا تزال أكبر بكثير من الأرض. هذه الكواكب الخارجية على الأرجح لها نوى صخرية محاطة بطبقات من الغازات والجليد المضغوط. تشكلت بعد خط الصقيع حيث يمكن للجليد أن يتكثف."},{"title_en":"Exoplanets","title_ar":"الكواكب الخارجية","content_en":"Exoplanets are planets orbiting stars beyond our solar system. Over 5,000 have been confirmed, with thousands more candidates. They range from hot Jupiters orbiting close to their stars to potentially habitable Earth-sized worlds in the \'Goldilocks zone\' where liquid water could exist. Detection methods include the transit method (observing dimming as planets pass in front of stars) and radial velocity (detecting stellar wobble). The James Webb Space Telescope is revolutionizing exoplanet science, analyzing their atmospheres for signs of life.","content_ar":"الكواكب الخارجية كواكب تدور حول نجوم خارج نظامنا الشمسي. أكثر من 5,000 تم تأكيدها، مع آلاف أخرى مرشحة. تتراوح من مشتريات ساخنة تدور قريباً من نجومها إلى عوالم بحجم الأرض محتملة السكن في \'منطقة المعتدل\' حيث يمكن أن يوجد ماء سائل. طرق الكشف تشمل طريقة العبور (مراقبة التعتيم بينما الكواكب تمر أمام النجوم) والسرعة الشعاعية (كشف تمايل النجم). تلسكوب جيمس ويب الفضائي يحدث ثورة في علم الكواكب الخارجية، يحلل أغلفتها الجوية بحثاً عن علامات الحياة."}]},{"id":"life","title_en":"Life","title_ar":"الحياة","icon":"\uD83C\uDF31","summary_en":"The search for life beyond Earth and the conditions that make it possible","summary_ar":"البحث عن الحياة خارج الأرض والظروف التي تجعلها ممكنة","sections":[{"title_en":"The Habitable Zone","title_ar":"المنطقة الصالحة للسكن","content_en":"The habitable zone, or \'Goldilocks zone\', is the region around a star where conditions might be right for liquid water to exist on a planet\'s surface - not too hot, not too cold. For our Sun, this zone extends roughly from Venus\'s orbit to Mars\'s orbit. However, habitability depends on many factors: planetary size, atmosphere, magnetic field, and geological activity. Some moons, like Europa and Enceladus, may be habitable despite being outside the traditional zone, warmed by tidal forces from their parent planets.","content_ar":"المنطقة الصالحة للسكن، أو \'منطقة المعتدل\'، هي المنطقة حول نجم حيث الظروف قد تكون مناسبة لوجود ماء سائل على سطح كوكب - ليست حارة جداً، ليست باردة جداً. لشمسنا، هذه المنطقة تمتد تقريباً من مدار الزهرة إلى مدار المريخ. لكن، قابلية السكن تعتمد على عوامل كثيرة: حجم الكوكب، الغلاف الجوي، المجال المغناطيسي، والنشاط الجيولوجي. بعض الأقمار، مثل أوروبا وإنسيلادوس، قد تكون قابلة للسكن رغم كونها خارج المنطقة التقليدية، مدفأة بقوى المد والجزر من كواكبها الأم."},{"title_en":"Life on Earth","title_ar":"الحياة على الأرض","content_en":"Earth is the only known planet with life. Life appeared relatively quickly after Earth formed, with evidence of microbial life dating back 3.7-4.1 billion years. Life has adapted to extreme environments: deep ocean vents, Antarctic ice, and acidic hot springs. This suggests life might exist in similar extreme environments elsewhere. Earth\'s life is based on carbon, uses water as a solvent, and relies on DNA/RNA for genetic information. However, life elsewhere might use different chemistries - silicon-based life, or life in liquid methane, remain theoretical possibilities.","content_ar":"الأرض الكوكب الوحيد المعروف الذي به حياة. الحياة ظهرت بسرعة نسبياً بعد تكوين الأرض، مع دليل على الحياة الميكروبية يعود إلى 3.7-4.1 مليار سنة. الحياة تكيفت مع بيئات متطرفة: فتحات المحيط العميقة، جليد القطب الجنوبي، والينابيع الساخنة الحمضية. هذا يقترح أن الحياة قد توجد في بيئات متطرفة مشابهة في أماكن أخرى. حياة الأرض مبنية على الكربون، تستخدم الماء كمذيب، وتعتمد على DNA/RNA للمعلومات الوراثية. لكن، الحياة في مكان آخر قد تستخدم كيمياء مختلفة - حياة مبنية على السيليكون، أو حياة في ميثان سائل، تبقى احتمالات نظرية."},{"title_en":"Search for Extraterrestrial Life","title_ar":"البحث عن الحياة خارج الأرض","content_en":"The search for extraterrestrial life includes SETI (Search for Extraterrestrial Intelligence) listening for radio signals, missions to Mars and icy moons seeking microbial life, and analysis of exoplanet atmospheres for biosignatures - chemical signs of life. The discovery of extremophiles on Earth expanded our understanding of where life might exist. Future missions will drill into Europa\'s ice, search Enceladus\'s plumes, and analyze samples from Mars. The James Webb Space Telescope can detect potential biosignatures like oxygen, methane, and other gases in exoplanet atmospheres.","content_ar":"البحث عن الحياة خارج الأرض يشمل SETI (البحث عن الذكاء خارج الأرض) الاستماع لإشارات الراديو، مهمات إلى المريخ والأقمار الجليدية بحثاً عن الحياة الميكروبية، وتحليل أغلفة الكواكب الخارجية للعلامات الحيوية - علامات كيميائية للحياة. اكتشاف المتطرفات على الأرض وسع فهمنا لأين قد توجد الحياة. المهمات المستقبلية ستحفر في جليد أوروبا، تبحث في أعمدة إنسيلادوس، وتحلل عينات من المريخ. تلسكوب جيمس ويب الفضائي يمكنه كشف العلامات الحيوية المحتملة مثل الأكسجين والميثان وغازات أخرى في أغلفة الكواكب الخارجية."},{"title_en":"Fermi Paradox","title_ar":"مفارقة فيرمي","content_en":"The Fermi Paradox asks: if the universe is so vast and old, where is everybody? Given the billions of stars and planets, intelligent life should be common, yet we see no evidence. Possible explanations include: life is rarer than we think, intelligent civilizations destroy themselves, we\'re looking in the wrong way, advanced civilizations are too different to recognize, or we\'re simply the first. The paradox highlights the profound questions about life\'s prevalence and our place in the cosmos.","content_ar":"مفارقة فيرمي تسأل: إذا كان الكون شاسعاً وعتيقاً جداً، أين الجميع؟ نظراً لمليارات النجوم والكواكب، الحياة الذكية يجب أن تكون شائعة، لكننا لا نرى دليلاً. التفسيرات المحتملة تشمل: الحياة أندر مما نعتقد، الحضارات الذكية تدمر نفسها، نبحث بالطريقة الخاطئة، الحضارات المتقدمة مختلفة جداً للتعرف عليها، أو ببساطة نحن الأولون. المفارقة تسلط الضوء على الأسئلة العميقة حول انتشار الحياة ومكاننا في الكون."}]},{"id":"missions","title_en":"Missions","title_ar":"المهمات","icon":"\uD83D\uDE80","summary_en":"Humanity\'s journey to explore space, from early rockets to future interstellar travel","summary_ar":"رحلة البشرية لاستكشاف الفضاء، من الصواريخ المبكرة إلى السفر بين النجوم المستقبلي","sections":[{"title_en":"Early Space Exploration","title_ar":"الاستكشاف الفضائي المبكر","content_en":"The space age began on October 4, 1957, when the Soviet Union launched Sputnik 1, the first artificial satellite. This sparked the Space Race between the US and USSR. Yuri Gagarin became the first human in space in 1961. The Apollo program achieved the first human Moon landing in 1969 with Apollo 11. These early missions proved humans could survive and work in space, established communication networks, and provided the first views of Earth from space, changing our perspective forever.","content_ar":"عصر الفضاء بدأ في 4 أكتوبر 1957، عندما أطلقت الاتحاد السوفيتي سبوتنيك 1، أول قمر صناعي. هذا أشعل سباق الفضاء بين الولايات المتحدة والاتحاد السوفيتي. يوري جاجارين أصبح أول إنسان في الفضاء في 1961. برنامج أبولو حقق أول هبوط بشري على القمر في 1969 مع أبولو 11. هذه المهمات المبكرة أثبتت أن البشر يمكنهم البقاء والعمل في الفضاء، أنشأت شبكات اتصال، ووفرت أول مناظر للأرض من الفضاء، مغيرين منظورنا للأبد."},{"title_en":"Modern Space Missions","title_ar":"المهمات الفضائية الحديثة","content_en":"Today\'s missions explore the entire solar system and beyond. Rovers like Perseverance search Mars for signs of past life. The James Webb Space Telescope peers into the early universe. Voyager probes have left the solar system, carrying messages to potential alien civilizations. The International Space Station serves as a laboratory and stepping stone for deeper space exploration. Private companies are revolutionizing space travel, making it more accessible. Missions to asteroids, comets, and outer planets reveal the diversity and history of our cosmic neighborhood.","content_ar":"مهمات اليوم تستكشف النظام الشمسي بأكمله وما بعده. المركبات الجوالة مثل المثابرة تبحث في المريخ عن علامات حياة سابقة. تلسكوب جيمس ويب الفضائي ينظر في الكون المبكر. مسبارات فوياجر تركت النظام الشمسي، حاملة رسائل لحضارات فضائية محتملة. محطة الفضاء الدولية تخدم كمختبر وحجر عثرة لاستكشاف فضاء أعمق. الشركات الخاصة تحدث ثورة في السفر الفضائي، تجعله أكثر سهولة. مهمات إلى الكويكبات والمذنبات والكواكب الخارجية تكشف التنوع وتاريخ جوارنا الكوني."},{"title_en":"Future Missions","title_ar":"المهمات المستقبلية","content_en":"Future missions aim to return humans to the Moon, establish permanent bases, and eventually send humans to Mars. The Artemis program plans to land the first woman and next man on the Moon by 2025. Mars sample return missions will bring Martian rocks to Earth for analysis. Missions to Europa and Enceladus will search for life in subsurface oceans. The search for habitable exoplanets continues. Interstellar probes, though decades away, are being designed. These missions will answer fundamental questions about life, the universe, and our place in it.","content_ar":"المهمات المستقبلية تهدف لإعادة البشر إلى القمر، إنشاء قواعد دائمة، وفي النهاية إرسال بشر إلى المريخ. برنامج أرتميس يخطط لهبوط أول امرأة والرجل التالي على القمر بحلول 2025. مهمات إرجاع عينات المريخ ستحضر صخور المريخ إلى الأرض للتحليل. مهمات إلى أوروبا وإنسيلادوس ستبحث عن الحياة في محيطات تحت السطح. البحث عن كواكب خارجية قابلة للسكن مستمر. مسبارات بين النجوم، رغم أنها بعيدة عقود، يتم تصميمها. هذه المهمات ستحلل أسئلة أساسية عن الحياة والكون ومكاننا فيه."},{"title_en":"Space Technology","title_ar":"التكنولوجيا الفضائية","content_en":"Space exploration drives technological innovation. Satellites enable global communication, GPS navigation, weather forecasting, and Earth observation. Space technology has led to innovations in materials science, computing, medicine, and energy. The International Space Station tests technologies for long-duration spaceflight. Future technologies include advanced propulsion systems, in-situ resource utilization (using local materials), life support systems, and radiation protection. These innovations benefit both space exploration and life on Earth.","content_ar":"استكشاف الفضاء يدفع الابتكار التكنولوجي. الأقمار الصناعية تمكن الاتصال العالمي، ملاحة GPS، التنبؤ بالطقس، ومراقبة الأرض. التكنولوجيا الفضائية أدت لابتكارات في علوم المواد، الحوسبة، الطب، والطاقة. محطة الفضاء الدولية تختبر تكنولوجيات لرحلات فضائية طويلة المدة. التكنولوجيات المستقبلية تشمل أنظمة دفع متقدمة، استخدام الموارد المحلية (استخدام المواد المحلية)، أنظمة دعم الحياة، والحماية من الإشعاع. هذه الابتكارات تفيد استكشاف الفضاء والحياة على الأرض."}]}]}')}}]);